<?php
session_start(); require_once '../conexion.php';
if(!isset($_SESSION['usuario_id'])||$_SESSION['rol']!=='admin'){header('Location: ../login.php');exit;}
$pedidos=array();$sql="SELECT p.id,p.estado,p.fecha,u.nombre AS operario,p.total_productos FROM pedidos p LEFT JOIN usuarios u ON p.operario_id=u.id ORDER BY p.id DESC";$resultado=$conexion->query($sql);if($resultado){while($fila=$resultado->fetch_assoc()){$pedidos[]=$fila;}}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Pedidos | Softyle</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../CSS/sistema.css"></head><body class="sistema-body"><nav class="sistema-navbar"><div class="navbar-brand-sistema"><div class="navbar-logo"><i class="bi bi-box-seam"></i></div><div><strong>SOFTYLE</strong><small>Panel administrativo</small></div></div><a href="dashboard.php" class="btn-logout"><i class="bi bi-arrow-left"></i></a></nav><main class="admin-container"><a href="dashboard.php" class="volver-link"><i class="bi bi-arrow-left"></i> Volver al panel</a><section class="dashboard-header"><span class="dashboard-label">GESTIÓN</span><h1>Pedidos</h1><p>Controlá el estado de los pedidos del depósito.</p></section><div class="admin-table-card"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Pedido</th><th>Operario</th><th>Productos</th><th>Estado</th><th>Fecha</th></tr></thead><tbody><?php if(count($pedidos)===0){?><tr><td colspan="5" class="text-center">No hay pedidos registrados.</td></tr><?php }?><?php foreach($pedidos as $pedido){?><tr><td><strong>#<?php echo (int)$pedido['id'];?></strong></td><td><?php echo $pedido['operario']?htmlspecialchars($pedido['operario'],ENT_QUOTES,'UTF-8'):'Sin asignar';?></td><td><?php echo (int)$pedido['total_productos'];?></td><td><?php if($pedido['estado']==='Completado'){?><span class="estado activo">Completado</span><?php }elseif($pedido['estado']==='En proceso'){?><span class="estado en-proceso">En proceso</span><?php }else{?><span class="estado">Pendiente</span><?php }?></td><td><?php echo htmlspecialchars($pedido['fecha'],ENT_QUOTES,'UTF-8');?></td></tr><?php }?></tbody></table></div></div></main></body></html>
